from pathlib import Path
import subprocess,numpy as np,json
r=Path(__file__).resolve().parents[1];a=Path('/tmp/ep10-expected.f32');b=Path('/tmp/ep10-final.f32')
subprocess.run(['ffmpeg','-v','error','-y','-i',str(r/'public/narration.mp3'),'-i',str(r/'public/original-background.wav'),'-i',str(r/'public/original-cues.wav'),'-filter_complex','[0:a]aresample=16000,aformat=channel_layouts=mono[v];[1:a]volume=0.19,aresample=16000,aformat=channel_layouts=mono[m];[2:a]volume=0.3,aresample=16000,aformat=channel_layouts=mono[c];[v][m][c]amix=inputs=3:normalize=0:duration=first','-f','f32le',str(a)],check=True)
subprocess.run(['ffmpeg','-v','error','-y','-i',str(r/'out/ep10-bakery.mp4'),'-vn','-ac','1','-ar','16000','-f','f32le',str(b)],check=True);x=np.fromfile(a,np.float32);y=np.fromfile(b,np.float32);n=min(len(x),len(y));corr=float(np.corrcoef(x[:n],y[:n])[0,1]);assert corr>.995,corr;peak=float(20*np.log10(np.max(np.abs(y))));assert peak<0;d=json.loads((r/'out/validation.json').read_text());d['audio_expected_mix_correlation']=corr;d['audio_peak_dbfs']=peak;d['audio_clipping']=False;(r/'out/validation.json').write_text(json.dumps(d,ensure_ascii=False,indent=2));print('Audio match',corr,'peak dBFS',peak)
